sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var html;
    var gr = new GlideRecord('x_ndecd_triage_2_0_pdftemplate');
    gr.addQuery('template_name', 'PDFTSA');
    gr.query();
    while (gr.next()) {
        html = gr.html_template;
    }

    //Données démographiques de l'élève
    var eleve = new GlideRecord('x_ndecd_triage_2_0_eleve');
    eleve.get(current.getValue('eleve'));
    html = html.replace('var1', eleve.name); //Name
    html = html.replace('var2', eleve.u_date_de_naissance); //Birthdate
    html = html.replace('var3', eleve.u_niso); //NISO
    html = html.replace('var4', eleve.getDisplayValue('u_nom_de_l_cole')); //School name
    html = html.replace('var5', eleve.getDisplayValue('u_classe')); //Class

    //Informations concernant l'élève
    html = html.replace('var6', getBoolean(current.est_ce_que_l_l_ve_fr_quente_pr_sentement_une_classe_distincte));
    html = html.replace('var7', current.est_ce_que_l_l_ve_a_un_diagnostic_pos_par_un_professionnel_de_la_sant_autoris);
    html = html.replace('var8', current.situation_familiale_de_l_l_ve);

    if (current.situation_familiale_de_l_l_ve == 'Autre situation') {
        html = html.replace('var9', current.autre_situation_explication);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Autre situation familiale: <strong>var9</strong></span></div>', '');
    }

    //DESCRIPTION DES BESOINS DE L’ÉLÈVE

    //Langues parlées
    html = html.replace('var20', current.getDisplayValue('langue_s_parl_e_s_la_maison'));
    html = html.replace('var21', current.getDisplayValue('langue_dominante_de_l_l_ve_la_langue_avec_laquelle_l_l_ve_est_le_plus_l_ais'));
    html = html.replace('var22', getBoolean(current.est_ce_que_des_difficult_s_langagi_res_sont_observ_es_dans_sa_langue_dominante));

    //Communication sociale
    html = html.replace('var30', current.getDisplayValue('l_l_ve_prouve_t_il_des_difficult_s_li_es_explication'));
    html = html.replace('var31', current.getDisplayValue('l_l_ve_prouve_t_il_des_difficult_s_r_guler_les_interactions_sociales_en_util'));

    if (current.l_l_ve_d_montre_t_il_de_l_int_r_t_partager_son_plaisir_ses_r_ussites_et_ses) {
        html = html.replace('var32', 'Non');
        html = html.replace('var33', current.getDisplayValue('l_l_ve_d_montre_t_il_de_l_int_r_t_partager_son_plaisir_ses_r_ussites_et_ses'));
    } else {
        html = html.replace('var32', 'Oui');
        html = html.replace('<div><span style="font-size: 10pt;">L’élève (cochez toutes les options qui s’appliquent):<strong> var33</strong></span></div>', '');
    }

    if (current.l_l_ve_prouve_t_il_des_difficult_s_former_des_relations_avec_ses_pairs_du_m) {
        html = html.replace('var34', 'Oui');
        html = html.replace('var35', current.getDisplayValue('l_l_ve_prouve_t_il_des_difficult_s_former_des_relations_avec_ses_pairs_du_m'));
    } else {
        html = html.replace('var34', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;"><span title="">L’élève (cochez toutes les options qui s’appliquent): </span><strong>var35</strong></span></div>', '');
    }

    //Compréhension langagière
    if (current.l_l_ve_d_montre_t_il_des_difficult_s_comprendre_le_langage_oral_explication) {
        html = html.replace('var40', 'Oui');
        html = html.replace('var41', current.getDisplayValue('l_l_ve_d_montre_t_il_des_difficult_s_comprendre_le_langage_oral_explication'));
    } else {
        html = html.replace('var40', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;"><span title="">L’élève démontre de la difficulté à comprendre (cochez toutes les options qui s’appliquent): </span><strong>var41</strong></span></div>', '');
    }

    //Habiletés expressives
    html = html.replace('var50', current.getDisplayValue('les_enfants_utilisent_souvent_plus_d_un_moyen_pour_exprimer_leurs_besoins'));

    //Routines/flexibilité
    if (current.difficult_s_au_niveau_de_la_routine_et_des_transitions) {
        html = html.replace('var60', 'Oui');
        html = html.replace('var61', current.getDisplayValue('difficult_s_au_niveau_de_la_routine_et_des_transitions'));
    } else {
        html = html.replace('var60', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;">L’élève (cochez toutes les options qui s’appliquent): <strong>var61</strong></span></div>', '');
    }

    //Jeu
    if (current.l_l_ve_pr_sente_t_il_des_difficult_s_au_niveau_des_habilet_s_li_es_au_jeu_ex) {
        html = html.replace('var70', 'Oui');
        html = html.replace('var71', current.getDisplayValue('l_l_ve_pr_sente_t_il_des_difficult_s_au_niveau_des_habilet_s_li_es_au_jeu_ex'));
    } else {
        html = html.replace('var70', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;">Veuillez cocher l’option qui s’applique le mieux à l’élève parmi les choix suivants: <strong>var71</strong></span></div>', '');
    }

    //Imitation
    if (current.l_l_ve_prouve_t_il_des_difficult_s_imiter) {
        html = html.replace('var80', 'Oui');
        html = html.replace('var81', current.getDisplayValue('l_l_ve_prouve_t_il_des_difficult_s_imiter'));
    } else {
        html = html.replace('var80', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;"><span title="">Choisissez l’énoncé qui décrit le mieux l’élève:</span><strong> var81</strong></span></div>', '');
    }

    //INFORMATIONS ADDITIONNELLES
    var services = current.getDisplayValue('l_l_ve_a_t_il_re_u_des_services_professionnels_dans_les_domaines_suivants');
    html = html.replace('var90', services);

    if (services.indexOf('Audiologie') > -1) {
        html = html.replace('var91', current.audiologie_date);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Audiologie date: <strong>var91</strong></span></div>', '');
    }

    if (services.indexOf('Optométrie') > -1) {
        html = html.replace('var92', current.optom_trie_date);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Optométrie date: <strong>var92</strong></span></div>', '');
    }

    if (services.indexOf('Ergothérapie') > -1) {
        html = html.replace('var93', current.ergoth_rapie_date);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Ergothérapie date: <strong>var93</strong></span></div>', '');
    }

    if (services.indexOf('Psychologie') > -1) {
        html = html.replace('var94', current.psychologie_date);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Psychologie date: <strong>var94</strong></span></div>', '');
    }

    if (services.indexOf('Travail social') > -1) {
        html = html.replace('var95', current.travail_social_date);
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Travail social date: <strong>var95</strong></span></div>', '');
    }

    if (services.indexOf('Orthophonie') > -1) {
        var services_ortho = current.getDisplayValue('orthophonie_explication');
        html = html.replace('var96', services_ortho);

        if (services_ortho.indexOf('Premiers Mots') > -1) {
            html = html.replace('var97', current.getDisplayValue('premiers_mots_date'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">Premiers Mots date: <strong>var97</strong></span></div>', '');
        }

        if (services_ortho.indexOf('SRMS') > -1) {
            html = html.replace('var98', current.getDisplayValue('srms_date'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">SRMS date: <strong>var98</strong></span></div>', '');
        }

        if (services_ortho.indexOf('Pratique privée') > -1) {
            html = html.replace('var99', current.getDisplayValue('pratique_priv_e_date'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">Pratique privée date: <strong>var99</strong></span></div>', '');
        }

        if (services_ortho.indexOf('Autre') > -1) {
            html = html.replace('var100', current.getDisplayValue('orthophonie_explication_autre'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">Autres services professionnels orthophonie: <strong>var100</strong></span></div>', '');
        }

    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Services professionnels orthophonie:<strong> var96</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">Premiers Mots date: <strong>var97</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">SRMS date: <strong>var98</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">Pratique privée date: <strong>var99</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">Autres services professionnels orthophonie: <strong>var100</strong></span></div>', '');
    }

    if (services.indexOf('Autre') > -1) {
        html = html.replace('var101', current.getDisplayValue('l_l_ve_a_t_il_re_u_des_services_professionnels_autre'));
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Autres services professionnels: <strong>var101</strong></span></div>', '');
    }

    if (current.est_ce_que_l_l_ve_pr_sente_un_diagnostic_m_dical_officiel_d_un_tsa_explication) {
        html = html.replace('var102', 'Oui');
        var diagnostics = current.getDisplayValue('est_ce_que_l_l_ve_pr_sente_un_diagnostic_m_dical_officiel_d_un_tsa_explication');
        html = html.replace('var103', diagnostics);

        if (diagnostics.indexOf('Syndrome génétique') > -1) {
            html = html.replace('var104', current.getDisplayValue('veuillez_pr_ciser_syndrome_g_n_tique'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser (Syndrome génétique):<strong> var104</strong></span></div>', '');
        }

        if (diagnostics.indexOf('Autres') > -1) {
            html = html.replace('var105', current.getDisplayValue('diagnostic_m_dical_officiel_d_un_tsa_explication_autre'));
        } else {
            html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser (Autres):<strong> var105</strong></span></div>', '');
        }


    } else {
        html = html.replace('var102', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser: <strong>var103</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser (Syndrome génétique):<strong> var104</strong></span></div>', '');

        html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser (Autres):<strong> var105</strong></span></div>', '');
    }

    if (current.est_ce_que_l_l_ve_est_en_attente_d_une_valuation_pouvant_mener_un_diagnostic) {
        html = html.replace('var106', 'Oui');
        html = html.replace('var107', current.getDisplayValue('est_ce_que_l_l_ve_est_en_attente_d_une_valuation_pouvant_mener_un_diagnostic'));
    } else {
        html = html.replace('var106', 'Non');
        html = html.replace('<div><span style="font-size: 10pt;">Veuillez préciser: <strong>var107</strong></span></div>', '');
    }

    html = html.replace('var108', current.getDisplayValue('est_ce_qu_un_placement_est_envisag_pour_l_l_ve'));

    if (current.est_ce_qu_un_placement_est_envisag_pour_l_l_ve == 'yes') {
        html = html.replace('var109', current.getDisplayValue('est_ce_que_les_parents_sont_en_accord_avec_cette_demande_de_placement'));
    } else {
        html = html.replace('<div><span style="font-size: 10pt;">Est-ce que les parents sont en accord avec cette demande de placement? <strong>var109</strong></span></div>', '');
    }

    //Attestation de l'équipe école
    html = html.replace("var110", current.getDisplayValue('opened_by'));
    html = html.replace("var111", current.getDisplayValue('opened_by'));

    var approver = new GlideRecord('sys_user');
    approver.addQuery('sys_id', current.opened_by.sys_id);
    approver.query();
    if (approver.next()) {
        html = html.replace("var112", approver.getDisplayValue('title'));
    }

    html = html.replace("var113", current.getDisplayValue('sys_created_on'));

    var dir = current.number;
    var gsdirect = new GlideRecord('sysapproval_approver');
    gsdirect.addQuery('sysapproval.number', dir);
    gsdirect.addQuery('state', 'approved');
    gsdirect.query();
    while (gsdirect.next()) {
        html = html.replace("var114", gsdirect.getDisplayValue('approver'));
        html = html.replace("var115", gsdirect.getDisplayValue('approver'));

        var approverSysId = gsdirect.approver.sys_id.toString();
        var grApprover = new GlideRecord('sys_user');
        grApprover.addQuery('sys_id', approverSysId);
        grApprover.query();
        if (grApprover.next()) {
            html = html.replace("var116", grApprover.title);
        }
    }
    html = html.replace("var117", current.getDisplayValue('sys_updated_on'));

    //Construire PDF
    var pdf_name = 'TSA ' + eleve.name;
    var table_name = 'x_ndecd_triage_2_0_demande_tsa';
    var table_sys_id = current.sys_id;

    var hfInfo = {
        HeaderImageAttachmentId: "fe71ca801b04b910d991c882604bcb30",
        HeaderImageAlignment: "left",
        FooterImageAttachmentId: "f69aa9661bf7a5108d594047bc4bcb1c",
        FooterImageAlignment: "TOP_CENTER",
        PageSize: "A4",
        GeneratePageNumber: "false",
        TopOrBottomMargin: "50",
        LeftOrRightMargin: "24"
    };

    var v = new sn_pdfgeneratorutils.PDFGenerationAPI;
    var result = v.convertToPDFWithHeaderFooter(html, table_name, table_sys_id, pdf_name, hfInfo);
    current.update();

})(current, previous);

function getBoolean(value) {
    if (value == 'yes') return 'Oui';
    else if (value == 'no') return 'Non';
    return value;
}
